DROP TABLE IF EXISTS `ownership_models`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ownership_models` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `units` bigint NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `listing_id` bigint unsigned NOT NULL,
  `ownership_type` varchar(100) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ownership_models_deleted_at` (`deleted_at`),
  KEY `idx_ownership_models_user_id` (`user_id`),
  KEY `idx_ownership_models_listing_id` (`listing_id`),
  CONSTRAINT `fk_ownership_models_listing` FOREIGN KEY (`listing_id`) REFERENCES `listing_models` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ownership_models_user` FOREIGN KEY (`user_id`) REFERENCES `user_models` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
