DROP TABLE IF EXISTS `user_models`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_models` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `name` varchar(2048) DEFAULT NULL,
  `phone` varchar(2048) DEFAULT NULL,
  `role_id` bigint unsigned NOT NULL,
  `status` varchar(2048) DEFAULT NULL,
  `location` varchar(2048) DEFAULT NULL,
  `password` longtext NOT NULL,
  `email` longtext,
  `token` longtext,
  `kyc_verified` tinyint(1) DEFAULT '0',
  `activation_fee_paid` tinyint(1) DEFAULT '0',
  `is_account_activated` tinyint(1) DEFAULT '0',
  `public_key` varchar(2048) DEFAULT NULL,
  `secret_key` varchar(2048) DEFAULT NULL,
  `pin` longtext NOT NULL,
  `cardano_address` varchar(256) DEFAULT NULL,
  `cardano_skey_cbor` varchar(1024) DEFAULT NULL,
  `cardano_vkey_cbor` varchar(1024) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user_models_deleted_at` (`deleted_at`),
  KEY `fk_user_models_role` (`role_id`),
  CONSTRAINT `fk_user_models_role` FOREIGN KEY (`role_id`) REFERENCES `roles_model` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=176 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

